def integer_nth_root(n, k):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def is_power_of_k(n, k):
    if n <= 0:
        return False
    x = 1
    while x < n:
        x *= k
    return x == n

def xor_of_range(a, b):
    def xor_upto(n):
        if n < 0:
            return 0
        r = n % 4
        if r == 0:
            return n
        elif r == 1:
            return 1
        elif r == 2:
            return n + 1
        else:
            return 0
    return xor_upto(b) ^ xor_upto(a - 1)

