def are_pairwise_coprime(nums):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if math.gcd(nums[i], nums[j]) != 1:
                return False
    return True

def count_trailing_zeros_binary(n):
    count = 0
    while n % 2 == 0:
        n //= 2
        count += 1
    return count

def is_semiprime(n):
    if n < 4:
        return False
    count = 0
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            temp //= d
            count += 1
            if count > 2:
                return False
        d += 1
    if temp > 1:
        count += 1
    return count == 2

