def smallest_multiple_up_to(n):
    result = 1
    for i in range(1, n + 1):
        result = result * i // math.gcd(result, i)
    return result

def sum_multiples_of_3_or_5_below(n):
    total = 0
    for i in range(1, n):
        if i % 3 == 0 or i % 5 == 0:
            total += i
    return total

def sum_of_proper_divisors(n):
    if n <= 1:
        return 0
    total = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            j = n // i
            if i != n:
                total += i
            if j != i and j != n:
                total += j
    return total

