def count_perfect_squares_up_to(n):
    if n < 1:
        return 0
    return math.isqrt(n)

def is_product_palindrome(a, b):
    p = str(a * b)
    return p == p[::-1]

def is_repdigit(n):
    s = str(abs(n))
    return len(set(s)) == 1
